<?php if(($pager['pages']??1)>1):?><nav class="mt-3"><ul class="pagination justify-content-center flex-wrap"><li class="page-item <?=$pager['page']<=1?'disabled':''?>"><a class="page-link" href="<?=e(pageUrl(max(1,$pager['page']-1)))?>">‹</a></li><?php $a=max(1,$pager['page']-2);$b=min($pager['pages'],$pager['page']+2);for($i=$a;$i<=$b;$i++):?><li class="page-item <?=$i===$pager['page']?'active':''?>"><a class="page-link" href="<?=e(pageUrl($i))?>"><?=$i?></a></li><?php endfor;?><li class="page-item <?=$pager['page']>=$pager['pages']?'disabled':''?>"><a class="page-link" href="<?=e(pageUrl(min($pager['pages'],$pager['page']+1)))?>">›</a></li></ul><div class="text-center text-muted small">Página <?=$pager['page']?> de <?=$pager['pages']?> · <?=$pager['total']?> registros</div></nav><?php endif;?>